'use strict';
function LocalizingManager(){
	this.strT = {};
}
LocalizingManager.prototype = {
	Init:function(cb){
		var xhr = new XMLHttpRequest();
		xhr.open("GET", "assets/font/Localizing_" + Define.LANG + ".txt", true);
		xhr.send(null);
		xhr.onload = function(){
			if(xhr.status != 404){
				this.strT = JSON.parse(xhr.responseText);
				if(cb) cb();
				console.log(this.strT);
			}
			else{
				throw alert(kData.lang + ' not file');
			}
		}.bind(this);
	},
	Get:function(key) {
		if(this.strT[key] == undefined)
			return key+" : null";

		var args = Array.prototype.slice.call(arguments, 1);
		if(args.length == 0)
			return this.strT[key];
		else{
			return this.strT[key].replace(/{(\d+)}/g, function(match, number) {
				return typeof args[number] != 'undefined'
					? args[number]
					: match
					;
			});
		}
	},
}
