/**
 * 스크롤바영역을 생성하고 반환합니다.
 *
 * @method getScrollView#UiManager
 */
UiManager.prototype.getScrollView = function(_x, _y, _width, _height, onUp, parent)
{
    var scroller = MG.game.add.existing(new ScrollableArea(MG.game, _x, _y, _width, _height, {}, onUp));
    scroller.items = new Array();
    scroller.areaWidth = _width;
    scroller.areaHeight = _height;
    scroller.itemOffsetX = 0;
    scroller.itemOffsetY = 0;

    scroller.addItem = function( obj )
    {
        scroller.addChild(obj);
        var gra = this.game.add.graphics(obj.x + this.itemOffsetX, obj.y + this.itemOffsetY);
        var objWidth = (obj.width == 0 || this.itemWidth>0) ? this.itemWidth : obj.width;
        var objHeight = (obj.height == 0 || this.itemHeight>0) ? this.itemHeight : obj.height;
        //console.log("objWidth : " + objWidth);
        //console.log("objHeight : " + objHeight);
        gra.beginFill(0x00ff00);
        gra.drawRect(0,0,objWidth,objHeight);
        gra.endFill();
        gra.alpha = 0;
        gra.inputEnabled = true;
        gra.game = this.game;
        gra.events.onInputUp.add(function(){ });
        scroller.addClickObject(gra, obj);
    }

    scroller.start();
    return scroller;
}// end of getScrollView

